/// <reference lib="webworker" />

// Generated by wasm-pack before Vite starts.
// @ts-ignore generated module is created by wasm-pack
import wasmInit, { initialize, detect } from './wasm/pkg/burn_yolo_inference.js';
// @ts-ignore generated WASM asset is created by wasm-pack
import wasmUrl from './wasm/pkg/burn_yolo_inference_bg.wasm?url';
import type { RuntimeEnvironment } from './lib/inference';

type Preference = 'cpu' | 'gpu' | 'auto';
type Request = {
  id: number;
  type: 'init' | 'detect';
  preference?: Preference;
  rgba?: Uint8Array;
  confidence?: number;
  iou?: number;
};

let wasmLoadMs = 0;
let wasmReady: Promise<void> | undefined;
function loadWasm(): Promise<void> {
  if (!wasmReady) {
    const start = performance.now();
    wasmReady = wasmInit({ module_or_path: wasmUrl }).then(() => {
      wasmLoadMs = performance.now() - start;
    });
  }
  return wasmReady!;
}

// This queries the *browser's default* adapter, not Burn's internal wgpu
// selection. Do not claim this is the exact device used by the Burn runtime.
type AdapterLike = {
  info?: { vendor?: string; architecture?: string; device?: string; description?: string; isFallbackAdapter?: boolean };
  features?: Iterable<string>;
  limits?: { maxBufferSize?: number; maxStorageBufferBindingSize?: number; maxComputeWorkgroupSizeX?: number };
};
type GpuLike = { requestAdapter(options?: { powerPreference?: 'low-power' | 'high-performance' }): Promise<AdapterLike | null> };
let environmentPromise: Promise<RuntimeEnvironment> | undefined;
function environment(): Promise<RuntimeEnvironment> {
  if (environmentPromise) return environmentPromise;
  environmentPromise = (async () => {
    const workerNavigator = navigator as WorkerNavigator & { gpu?: GpuLike; deviceMemory?: number };
    const result: RuntimeEnvironment = {
      userAgent: workerNavigator.userAgent,
      hardwareConcurrency: workerNavigator.hardwareConcurrency ?? null,
      deviceMemoryGiB: workerNavigator.deviceMemory ?? null,
      isSecureContext: self.isSecureContext,
      crossOriginIsolated: self.crossOriginIsolated,
      workerWebGpuAvailable: Boolean(workerNavigator.gpu),
      adapter: null,
      adapterNote: 'Browser default WebGPU adapter; Burn may select a different adapter or device.',
    };
    if (!workerNavigator.gpu) return result;
    try {
      const adapter = await workerNavigator.gpu.requestAdapter();
      if (!adapter) {
        result.adapterNote += ' Adapter request returned null.';
        return result;
      }
      const info = adapter.info;
      result.adapter = {
        vendor: info?.vendor || 'unavailable',
        architecture: info?.architecture || 'unavailable',
        device: info?.device || 'unavailable',
        description: info?.description || 'unavailable',
        isFallbackAdapter: info?.isFallbackAdapter ?? null,
        features: [...(adapter.features ?? [])].sort(),
        maxBufferSize: adapter.limits?.maxBufferSize ?? null,
        maxStorageBufferBindingSize: adapter.limits?.maxStorageBufferBindingSize ?? null,
        maxComputeWorkgroupSizeX: adapter.limits?.maxComputeWorkgroupSizeX ?? null,
      };
    } catch (e) {
      result.adapterNote += ` Adapter query failed: ${String(e)}`;
    }
    return result;
  })();
  return environmentPromise;
}

// All initialization and inference requests share one serialized Worker queue.
// This avoids switching device while a forward pass is active.
let chain: Promise<void> = Promise.resolve();
self.onmessage = (event: MessageEvent<Request>) => {
  const msg = event.data;
  const arrival = performance.now();
  chain = chain.catch(() => undefined).then(async () => {
    const start = performance.now();
    try {
      await loadWasm();
      let value: unknown;
      if (msg.type === 'init') {
        const initMetrics = await initialize(msg.preference ?? 'auto');
        // Probe *after* Burn has initialized to avoid competing with GPU startup.
        value = {
          ...initMetrics,
          environment: await environment(),
          wasmLoadMs,
          queueWaitMs: start - arrival,
          workerWallMs: performance.now() - start,
        };
      } else if (msg.type === 'detect') {
        if (!msg.rgba) throw new Error('No RGBA pixels supplied');
        const wasmStart = performance.now();
        const report = await detect(msg.rgba, msg.confidence ?? 0.25, msg.iou ?? 0.45);
        value = {
          ...report,
          wasmCallWallMs: performance.now() - wasmStart,
          queueWaitMs: start - arrival,
          workerWallMs: performance.now() - start,
        };
      } else {
        throw new Error('Unknown worker request');
      }
      self.postMessage({ id: msg.id, ok: true, value });
    } catch (error) {
      self.postMessage({ id: msg.id, ok: false, error: String(error) });
    }
  });
};
